import sqlite3
import numpy as np
from pymilvus import connections, Collection
from sentence_transformers import SentenceTransformer

# Step 0: Setup and connect to databases
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db"
}

milvus_config = {
    'milvus_collections': {
        'reviews': 'reviews',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530'
}

# Connect to Milvus
connections.connect(host=milvus_config['milvus_host'], port=milvus_config['milvus_port'])

# Load embedding model
model = SentenceTransformer('all-MiniLM-L6-v2')

# Step 1: Get Chinese restaurants in Tampa
conn_business = sqlite3.connect(sqlite_paths['business'])
cursor = conn_business.cursor()
cursor.execute("""
    SELECT business_id, name, address 
    FROM business 
    WHERE city = ? AND categories LIKE ?
""", ('Tampa', '%Chinese%'))

chinese_restaurants = cursor.fetchall()
conn_business.close()

if not chinese_restaurants:
    print('No Chinese restaurants found in Tampa.')
else:
    business_ids = [row[0] for row in chinese_restaurants]
    business_dict = {row[0]: {'name': row[1], 'address': row[2]} for row in chinese_restaurants}

    # Step 2: Vector search in reviews and tips
    queries = ['nice atmosphere', 'friendly service']
    query_embeddings = model.encode(queries)

    # Prepare results storage
    relevance_scores = {bid: 0.0 for bid in business_ids}
    supporting_snippets = {bid: [] for bid in business_ids}

    # Search in reviews
    try:
        reviews_col = Collection(milvus_config['milvus_collections']['reviews'])
        reviews_col.load()
        for emb in query_embeddings:
            search_params = {"metric_type": "L2", "params": {"nprobe": 10}}
            results = reviews_col.search(
                data=[emb.tolist()],
                anns_field="embedding",
                param=search_params,
                limit=20,
                expr=f"business_id in [{','.join([f'\"{bid}\"' for bid in business_ids])}]"
            )
            for hits in results:
                for hit in hits:
                    bid = hit.entity.get('business_id')
                    if bid in relevance_scores:
                        relevance_scores[bid] += (1.0 / (hit.distance + 1e-5))  # higher score for lower distance
                        supporting_snippets[bid].append(hit.entity.get('text', ''))
    except Exception as e:
        print(f"Error searching reviews: {e}")

    # Search in tips
    try:
        tips_col = Collection(milvus_config['milvus_collections']['tips'])
        tips_col.load()
        for emb in query_embeddings:
            search_params = {"metric_type": "L2", "params": {"nprobe": 10}}
            results = tips_col.search(
                data=[emb.tolist()],
                anns_field="embedding",
                param=search_params,
                limit=10,
                expr=f"business_id in [{','.join([f'\"{bid}\"' for bid in business_ids])}]"
            )
            for hits in results:
                for hit in hits:
                    bid = hit.entity.get('business_id')
                    if bid in relevance_scores:
                        relevance_scores[bid] += (1.0 / (hit.distance + 1e-5))
                        supporting_snippets[bid].append(hit.entity.get('text', ''))
    except Exception as e:
        print(f"Error searching tips: {e}")

    # Step 3: Rank and output
    ranked = sorted(relevance_scores.items(), key=lambda x: x[1], reverse=True)
    top_n = 5
    print("\nTop Chinese Restaurants in Tampa with Nice Atmosphere & Friendly Service:\n")
    count = 0
    for bid, score in ranked:
        if score > 0 and count < top_n:
            info = business_dict[bid]
            print(f"Name: {info['name']}")
            print(f"Address: {info['address']}")
            print(f"Relevance Score: {score:.2f}")
            if supporting_snippets[bid]:
                print("Supporting comments:")
                for snippet in supporting_snippets[bid][:2]:
                    print(f"  - {snippet}")
            print("-" * 50)
            count += 1

    if count == 0:
        print("No relevant reviews/tips found matching your criteria.")
